function uploadSlot($field,$prefix,$allowed,$max=100000000){global $uploadDir;if(empty($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK)return 'Upload failed.';if($f['size']>$max)return 'File is too large.';$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))return 'Invalid file type.';foreach(glob($uploadDir.$prefix.'.*') as $old) @unlink($old);$target=$uploadDir.$prefix.'.'.$ext;return move_uploaded_file($f['tmp_name'],$target)?null:'Could not save file.';}
