<div class="box"><h2>Current Files</h2><div class="grid"><?php foreach(glob($uploadDir.'*') as $p): $f=basename($p); ?><div class="item"><strong><?php echo clean($f); ?></strong><form method="post" onsubmit="return confirm('Delete this file?')"><input type="hidden" name="file" value="<?php echo clean($f); ?>"><button class="danger" name="delete">Delete</button></form></div><?php endforeach; if(!glob($uploadDir.'*')): ?><p>No uploads yet.</p><?php endif; ?></div></div>
<p><a href="index.php">← View Public Portfolio</a></p></div><script>const kind=document.getElementById('kind'),slot=document.getElementById('slot'),asset=document.getElementById('asset');function fill(){let n=kind.value==='video'?14:kind.value==='thumb'?4:5;slot.innerHTML='';for(let i=1;i<=n;i++){let o=document.createElement('option');o.value=i;o.textContent=String(i).padStart(2,'0');slot.appendChild(o)}asset.accept=kind.value==='video'?'video/*':'image/*'}kind.onchange=fill;fill();</script></body></html>
